"""Waiting evidence is mandatory; matching generated bytes never grant authority."""
import copy
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tools'))
import audit_a23_waiting_collection as audit
import collect_a23_waiting_execution as c


class WaitingCollectionTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.tmp=tempfile.TemporaryDirectory();cls.base=Path(cls.tmp.name).resolve();cls.review=cls.base/'review'
        cls.audit=audit.run(cls.review)

    @classmethod
    def tearDownClass(cls):cls.tmp.cleanup()

    def row(self,name='matching'):return self.audit['collection_cases'][name]['analysis']
    def packet(self,name='matching'):return self.review/'collections'/name
    def cloned(self,name='matching'):
        p=Path(tempfile.mkdtemp(dir=self.base))/'packet';shutil.copytree(self.packet(name),p);return p
    def reseal(self,p):
        files=c.packet_tree(p);files.pop('SHA256SUMS',None);files.pop('COMMITTED',None)
        sums=''.join(c.core.sha(b)+'  '+n+'\n' for n,b in sorted(files.items())).encode()
        (p/'SHA256SUMS').write_bytes(sums);(p/'COMMITTED').write_text(c.core.sha(sums)+'\n')

    def test_matching_generated_material_is_complete_but_never_authenticated(self):
        row=self.row();self.assertTrue(row['supplied_chain_consistent']);self.assertTrue(row['supplied_chain_complete'])
        self.assertTrue(row['waiting']['checkpoint_matches_reported']);self.assertEqual(row['waiting']['recorded_state'],'started_closed')
        self.assertEqual(self.audit['native_execution_count'],5);self.assertEqual(self.audit['collection_count'],24)
        for model in self.audit['native_models'].values():self.assertEqual((model['records'],model['identities']),(48,6));self.assertTrue(model['simulation'])
        for packet in self.audit['collection_cases'].values():
            self.assertTrue(packet['collection_integrity_verified'])
            for flag in c.POLICY:self.assertIs(packet[flag],False);self.assertIs(packet['analysis'][flag],False)

    def test_missing_wait_or_entry_cannot_inherit_the_old_positive_comparison(self):
        for name in ('missing-wait','missing-entry'):
            row=self.row(name);self.assertTrue(row['execution']['supplied_comparison_consistent'])
            self.assertFalse(row['waiting']['audit_valid']);self.assertFalse(row['supplied_chain_consistent']);self.assertFalse(row['supplied_chain_complete'])

    def test_wait_binding_and_reported_checkpoint_lifecycle_must_agree(self):
        for name in ('waiting-binding','result-contradiction','outer-lifecycle'):
            row=self.row(name);self.assertTrue(row['execution']['supplied_comparison_consistent'])
            self.assertFalse(row['waiting']['audit_valid']);self.assertFalse(row['supplied_chain_consistent'])
        self.assertIn('checkpoint',self.row('result-contradiction')['waiting']['errors'][0]['detail'])
        self.assertIn('lifecycle',self.row('outer-lifecycle')['waiting']['errors'][0]['detail'])

    def test_forged_preflight_and_wrong_checkpoint_types_are_rejected(self):
        for fault in ('preflight-has-started-driver','preflight-has-sdk-requests','boolean-ticks','unacknowledged-checkpoint','integer-wait-flag'):
            with self.subTest(fault=fault):
                p=self.cloned();f=p/'host/waiting-entry-result.json';r=json.loads(f.read_bytes())
                if fault.startswith('preflight'):
                    r.update(started=False,preflight_failed=True,finished=True,unresolved=False)
                    if fault=='preflight-has-sdk-requests':r['host_result']=None
                elif fault=='boolean-ticks':r['host_result']['ticks']=True
                elif fault=='unacknowledged-checkpoint':r['host_result']['final_checkpoint_saved']=False
                else:r['waiter_closed']=1
                f.write_bytes(c.core.canonical(r))
                checked=c.analyze_waiting(p/'host');self.assertFalse(checked['audit_valid']);self.assertTrue(checked['errors'])

    def test_partial_and_malformed_wait_sdk_and_execution_bytes_are_kept(self):
        for name,file in (('partial-wait','wait.jsonl'),('malformed-wait','wait.jsonl'),('partial-sdk','session.jsonl'),('malformed-sdk','session.jsonl')):
            self.assertEqual((self.review/'supplied'/name/file).read_bytes(),(self.packet(name)/'host'/file).read_bytes())
            self.assertFalse(self.row(name)['supplied_chain_complete']);self.assertTrue(self.row(name)['errors'])
        self.assertEqual((self.packet('partial-execution')/'execution.bin').read_bytes(),(self.review/'partial-execution.bin').read_bytes())
        self.assertFalse(self.row('partial-execution')['execution']['execution_valid'])
        self.assertTrue(self.row('malformed-sdk')['execution']['execution_valid'])

    def test_partial_original_and_failed_receipt_do_not_become_complete(self):
        for name in ('primary-receipt-failure','receipt-failure-partial-primary'):
            row=self.row(name);self.assertTrue(row['supplied_chain_consistent']);self.assertFalse(row['supplied_chain_complete'])
            self.assertFalse(row['primary_material_complete']);self.assertFalse(row['execution']['execution']['primary_receipt']['commit_acknowledged'])
        row=self.row('receipt-failure-partial-primary');self.assertFalse(row['execution']['external_primary_matches_embedded'])
        self.assertFalse(row['execution']['primary_commit_contradiction'])

    def test_committed_primary_disagreement_and_missing_original_are_distinct(self):
        row=self.row('different-primary');self.assertTrue(row['execution']['primary_commit_contradiction']);self.assertFalse(row['supplied_chain_consistent'])
        row=self.row('missing-primary');self.assertTrue(row['supplied_chain_consistent']);self.assertFalse(row['primary_material_complete']);self.assertFalse(row['supplied_chain_complete'])

    def test_request_shape_state_sequence_and_recipe_must_match_independently(self):
        for name in ('shape-mismatch','sequence-mismatch','wrong-recipe'):
            row=self.row(name);self.assertTrue(row['waiting']['audit_valid']);self.assertFalse(row['supplied_chain_consistent'])
        self.assertFalse(self.row('shape-mismatch')['execution']['comparison']['exact_target_setup_order_matches'])
        self.assertFalse(self.row('sequence-mismatch')['execution']['comparison']['status_state_sequence_matches'])
        self.assertFalse(self.row('wrong-recipe')['execution']['execution_valid'])

    def test_independent_device_clock_is_not_subtracted_from_the_host_clock(self):
        row=self.row('large-clock');self.assertTrue(row['supplied_chain_complete'])
        window=row['execution']['execution']['window'];self.assertGreater(window['start_tick'],10**18);self.assertEqual(window['frequency'],700000003)
        self.assertIs(row['cross_clock_alignment_verified'],False);self.assertIs(row['same_physical_run_verified'],False)

    def test_retained_preflight_and_failed_log_ack_never_become_closed_success(self):
        row=self.row('retained-iso');self.assertTrue(row['waiting']['audit_valid']);self.assertTrue(row['waiting']['checkpoint_matches_reported'])
        self.assertEqual(row['waiting']['recorded_state'],'started_unresolved');self.assertFalse(row['supplied_chain_complete'])
        self.assertEqual(self.row('preflight')['waiting']['recorded_state'],'preflight_failure')
        self.assertFalse(self.row('pre-wait-signal')['waiting']['audit_valid'])
        row=self.row('failed-journal-ack');self.assertTrue(row['waiting']['wait_journal_failed']);self.assertFalse(row['supplied_chain_consistent'])

    def test_original_failed_run_and_current_sources_tickets_remain_unchanged(self):
        row=self.row('historical-failure');self.assertTrue(row['execution']['host_audit_valid']);self.assertFalse(row['execution']['host_observation_complete'])
        self.assertFalse(row['waiting']['audit_valid']);self.assertFalse(row['root_cause_confirmed'])
        for name,digest in self.audit['source_hashes'].items():self.assertEqual(audit.builder.sha(audit.builder.plain(audit.REPO/name)),digest)
        for name,digest in self.audit['tickets_sha256'].items():self.assertEqual(audit.builder.sha(audit.builder.plain(audit.PARENT.parent/name)),digest)

    def test_tampered_raw_bytes_manifest_or_commit_are_rejected(self):
        for fault in ('raw','manifest','commit'):
            p=self.cloned()
            if fault=='raw':f=p/'execution.bin';raw=bytearray(f.read_bytes());raw[-1]^=1;f.write_bytes(raw)
            elif fault=='manifest':(p/'SHA256SUMS').write_bytes((p/'SHA256SUMS').read_bytes()[:-8])
            else:(p/'COMMITTED').write_text('0'*64+'\n')
            with self.assertRaises(ValueError):c.analyze_collection(p)

    def test_rehashed_policy_summary_and_inventory_forgery_are_rejected(self):
        for fault in ('analysis-policy','metadata-policy','summary','inventory','required','duplicate'):
            p=self.cloned('missing-wait' if fault=='summary' else 'matching')
            name='collection.json' if fault in ('metadata-policy','inventory','required') else 'analysis.json'
            f=p/name;value=json.loads(f.read_bytes())
            if fault.endswith('policy'):value['hardware_verified']=True
            elif fault=='summary':value['supplied_chain_consistent']=True
            elif fault=='inventory':value['raw_files']['execution.bin']['bytes']=True
            elif fault=='required':value['waiting_check_required']=False
            raw=c.core.canonical(value)
            if fault=='duplicate':raw=raw.replace(b'{',b'{"offline_only":false,',1)
            f.write_bytes(raw);self.reseal(p)
            with self.assertRaises(ValueError):c.analyze_collection(p)

    def test_existing_output_overlapping_source_and_symlinks_reject_before_copy(self):
        p=self.cloned();before=(p/'SHA256SUMS').read_bytes()
        with self.assertRaises(ValueError):c.freeze(p/'host',p/'execution.bin',p,audit.RECIPE)
        self.assertEqual((p/'SHA256SUMS').read_bytes(),before)
        with self.assertRaises(ValueError):c.freeze(p/'host',p/'execution.bin',p/'host/new-packet',audit.RECIPE)
        host=Path(tempfile.mkdtemp(dir=self.base));(host/'alias').symlink_to(p/'execution.bin');out=host.parent/(host.name+'-packet')
        with self.assertRaises(ValueError):c.freeze(host,p/'execution.bin',out,audit.RECIPE)
        self.assertFalse(out.exists())
        alias=host/'execution-alias.bin';alias.symlink_to(p/'execution.bin')
        with self.assertRaises(ValueError):c.freeze(p/'host',alias,out,audit.RECIPE)

    def test_source_change_after_copy_prevents_commit_and_keeps_original_copy(self):
        source=self.cloned();out=source.parent/'changed-packet';original=c.durable_write
        before=(source/'host/wait.jsonl').read_bytes()
        def write(path,raw):
            original(path,raw)
            if Path(path)==out/'analysis.json':(source/'host/wait.jsonl').write_bytes(b'changed during collection\n')
        with patch.object(c,'durable_write',side_effect=write):
            with self.assertRaisesRegex(ValueError,'source changed'):c.freeze(source/'host',source/'execution.bin',out,audit.RECIPE,source/'primary.bin')
        self.assertFalse((out/'COMMITTED').exists());self.assertEqual((out/'host/wait.jsonl').read_bytes(),before)

    def test_change_during_waiting_analysis_cannot_publish_a_result(self):
        p=self.cloned();original=c.waiting.analyze
        def analyze(host):
            result=original(host);f=Path(host)/'wait.jsonl';f.write_bytes(f.read_bytes()+b'changed\n');return result
        with patch.object(c.waiting,'analyze',side_effect=analyze):
            with self.assertRaises(ValueError):c.analyze_collection(p)

    def test_relocation_replays_the_same_positive_and_failure_results(self):
        for name in ('matching','partial-wait','malformed-sdk','pre-wait-signal'):
            p=self.cloned(name);result=c.analyze_collection(p)
            self.assertEqual(result,self.audit['collection_cases'][name])

    def test_nested_host_files_are_preserved_and_extra_root_entries_rejected(self):
        source=self.cloned();f=source/'host/a/b/c/d/note.txt';f.parent.mkdir(parents=True);f.write_bytes(b'unchanged unknown supplied bytes\x00')
        out=source.parent/'deep-packet';result=c.freeze(source/'host',source/'execution.bin',out,audit.RECIPE,source/'primary.bin')
        self.assertTrue(result['analysis']['supplied_chain_complete']);self.assertEqual((out/'host/a/b/c/d/note.txt').read_bytes(),f.read_bytes())
        (out/'extra-empty').mkdir()
        with self.assertRaises(ValueError):c.analyze_collection(out)

    def test_cli_reanalysis_is_read_only_and_does_not_execute_receiver(self):
        p=self.cloned();before=c.packet_tree(p)
        process=subprocess.run([sys.executable,str(ROOT/'tools/collect_a23_waiting_execution.py'),'analyze',str(p)],capture_output=True,text=True,check=True)
        self.assertTrue(json.loads(process.stdout)['analysis']['supplied_chain_complete']);self.assertEqual(c.packet_tree(p),before)


if __name__=='__main__':unittest.main()
